  inviter_name?: string
  invitee_user_id: number
  invitee_name?: string
  invitee_email?: string
  role: string
  status: string
  invited_at: string
  responded_at?: string
  last_sent_at: string
  can_resend: boolean
}

export interface ProjectDrawing {
  id: number
  project_id: number
  draw_id: string
  created_by: number
