126	// HandleWikiPagePDF generates a PDF of a wiki page that visually matches
127	// the web rendering. Uses headless Chromium via chromedp.
128	func (s *Server) HandleWikiPagePDF(w http.ResponseWriter, r *http.Request) {
129		ctx, cancel := context.WithTimeout(r.Context(), 30*time.Second)
130		defer cancel()
131	
132		userID := r.Context().Value(UserIDKey).(int64)
133		pageID, err := strconv.ParseInt(chi.URLParam(r, "pageId"), 10, 64)
134		if err != nil {
135			respondError(w, http.StatusBadRequest, "invalid page ID", "invalid_input")
136			return
137		}
138	
139		page, err := s.fetchWikiPageWithAccess(ctx, userID, pageID)
140		if err != nil {
141			s.handleWikiPageError(w, err, pageID)
142			return
143		}
144	
145		// Render markdown → HTML using the same pipeline as the preview endpoint.
146		renderedHTML := stripDrawEditMode(
147			wiki.RenderContent(
148				preprocessFigmaShortcodes(
149					preprocessGraphLinksForPreview(page.Content),
150				),
151			),
152		)
153	
154		htmlDoc := fmt.Sprintf(pdfHTMLTemplate, page.Title, pdfCSS, page.Title, renderedHTML)
155	
156		pdfBytes, err := renderHTMLToPDF(ctx, htmlDoc)
157		if err != nil {
158			s.logger.Error("Failed to generate wiki PDF",
159				zap.Int64("page_id", pageID),
160				zap.Error(err),
161			)
162			respondError(w, http.StatusInternalServerError, "failed to generate PDF", "internal_error")
163			return
164		}
165	
166		filename := page.Slug + ".pdf"
167		w.Header().Set("Content-Type", "application/pdf")
168		w.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="%s"`, filename))
169		w.Header().Set("Content-Length", strconv.Itoa(len(pdfBytes)))
170		w.WriteHeader(http.StatusOK)
171		w.Write(pdfBytes) //nolint:errcheck
172	}
173	
174	// HandleWikiPageMarkdown serves the raw markdown content of a wiki page as
175	// a downloadable .md file.
176	func (s *Server) HandleWikiPageMarkdown(w http.ResponseWriter, r *http.Request) {
177		ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
178		defer cancel()
179	
180		userID := r.Context().Value(UserIDKey).(int64)
181		pageID, err := strconv.ParseInt(chi.URLParam(r, "pageId"), 10, 64)
182		if err != nil {
183			respondError(w, http.StatusBadRequest, "invalid page ID", "invalid_input")
184			return
185		}
186	
187		pg, err := s.fetchWikiPageWithAccess(ctx, userID, pageID)
188		if err != nil {
189			s.handleWikiPageError(w, err, pageID)
190			return
191		}
192	
193		filename := pg.Slug + ".md"
194		w.Header().Set("Content-Type", "text/markdown; charset=utf-8")
195		w.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="%s"`, filename))
196		w.Header().Set("Content-Length", strconv.Itoa(len(pg.Content)))
197		w.WriteHeader(http.StatusOK)
198		w.Write([]byte(pg.Content)) //nolint:errcheck
199	}
200	
201	// ── helpers ─────────────────────────────────────────────────────────
202	
203	// fetchWikiPageWithAccess loads a wiki page and verifies user access.
204	func (s *Server) fetchWikiPageWithAccess(ctx context.Context, userID, pageID int64) (*ent.WikiPage, error) {
205		pg, err := s.db.Client.WikiPage.Query().
206			Where(wikipage.ID(pageID)).
207			Only(ctx)
208		if err != nil {
209			return nil, err
210		}
211	
212		hasAccess, err := s.checkProjectAccess(ctx, userID, pg.ProjectID)
213		if err != nil {
214			return nil, fmt.Errorf("access check: %w", err)
215		}
216		if !hasAccess {
217			return nil, errForbidden
218		}
219		return pg, nil
220	}
221	
222	// handleWikiPageError maps common errors to HTTP responses.
223	func (s *Server) handleWikiPageError(w http.ResponseWriter, err error, pageID int64) {
224		if ent.IsNotFound(err) {
225			respondError(w, http.StatusNotFound, "wiki page not found", "not_found")
226			return
227		}
228		if err == errForbidden {
229			respondError(w, http.StatusForbidden, "access denied", "forbidden")
230			return
231		}
232		s.logger.Error("Wiki page error", zap.Int64("page_id", pageID), zap.Error(err))
233		respondError(w, http.StatusInternalServerError, "internal error", "internal_error")
234	}
235	
236	// errForbidden is a sentinel for access-denied conditions.
237	var errForbidden = fmt.Errorf("forbidden")
238	
239	// renderHTMLToPDF launches headless Chromium to print the given HTML to PDF.
240	func renderHTMLToPDF(ctx context.Context, htmlContent string) ([]byte, error) {
241		allocOpts := append(chromedp.DefaultExecAllocatorOptions[:],
242			chromedp.NoSandbox,
243			chromedp.DisableGPU,
244			chromedp.Flag("disable-dev-shm-usage", true),
245		)
246	
247		allocCtx, allocCancel := chromedp.NewExecAllocator(ctx, allocOpts...)
248		defer allocCancel()
249	
250		taskCtx, taskCancel := chromedp.NewContext(allocCtx)
251		defer taskCancel()
252	
253		var pdfBuf []byte
254		if err := chromedp.Run(taskCtx,
255			chromedp.Navigate("about:blank"),
256			chromedp.ActionFunc(func(ctx context.Context) error {
257				frameTree, err := page.GetFrameTree().Do(ctx)
258				if err != nil {
259					return fmt.Errorf("get frame tree: %w", err)
260				}
261				return page.SetDocumentContent(frameTree.Frame.ID, htmlContent).Do(ctx)
262			}),
263			// Give the browser a moment to lay out styles.
264			chromedp.Sleep(200*time.Millisecond),
265			chromedp.ActionFunc(func(ctx context.Context) error {
266				var err error
267				pdfBuf, _, err = page.PrintToPDF().
268					WithPrintBackground(true).
269					WithMarginTop(0.6).
270					WithMarginBottom(0.6).
271					WithMarginLeft(0.5).
272					WithMarginRight(0.5).
273					WithPreferCSSPageSize(true).
274					Do(ctx)
275				return err
276			}),
277		); err != nil {
278			return nil, fmt.Errorf("chromedp run: %w", err)
279		}
280	
281		return pdfBuf, nil
282	}
